#!/usr/bin/env bash
# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-typst.sh -- Installs/updates Typst (document typesetting / PDF compiler)
# Safe to re-run -- detects existing install and upgrades as needed.
#
# macOS: Uses Homebrew (preferred). Removes non-preferred installs (cargo, npm).
#
# See reference/tool-registry.md for install source details.

set -euo pipefail

# --- Shared library ---
# aitools-lib.sh -- shared helpers for all aitools bash scripts
# Sourced, not executed directly. No shebang, no set -euo pipefail (caller sets it).
#
# Provides: platform detection, display_path, read_config_key, logging_init,
# log/log_ok/log_error/log_warn, write_summary, show_summary.
#
# Usage:
#   source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/aitools-lib.sh"
#   logging_init "script-name"
#
# Entry points (aitools, aitools-install) override log functions after sourcing
# for specialized logging (file-only, JSONL, etc.).

# ---------------------------------------------------------------------------
# Platform detection
# ---------------------------------------------------------------------------
IS_MACOS=false
IS_WINDOWS=false
case "$(uname -s)" in
    Darwin*)              IS_MACOS=true ;;
    MINGW*|MSYS*|CYGWIN*) IS_WINDOWS=true ;;
esac

# ---------------------------------------------------------------------------
# Log directory (platform-aware)
# ---------------------------------------------------------------------------
AITOOLS_LOG_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/aitools"
$IS_MACOS && AITOOLS_LOG_DIR="$HOME/Library/Logs/aitools"

# ---------------------------------------------------------------------------
# Display-friendly path (native Windows on MSYS, no-op elsewhere)
# ---------------------------------------------------------------------------
display_path() {
    if command -v cygpath &>/dev/null; then
        cygpath -w "$1"
    else
        printf '%s' "$1"
    fi
}

# ---------------------------------------------------------------------------
# Config reader (pure bash, handles UTF-8 BOM)
# ---------------------------------------------------------------------------
# Read a top-level string value from a JSON config file.
# Handles UTF-8 BOM (PowerShell 5.x writes one) and JSON-escaped backslashes.
read_config_key() {
    local file="$1" key="$2"
    [ -f "$file" ] || return 1
    local val
    val=$(tr -d '\357\273\277' < "$file" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | cut -d'"' -f4)
    [ -n "$val" ] || return 1
    # Unescape JSON backslashes: \\ -> \
    printf '%b' "$val"
}

# ---------------------------------------------------------------------------
# Logging init
# ---------------------------------------------------------------------------
# Sets SCRIPT_NAME, LOG_DIR, LOG_FILE, ERRORS, creates log dir.
# Usage: logging_init "setup-foo"
logging_init() {
    SCRIPT_NAME="${1:?logging_init requires a script name}"
    LOG_DIR="$AITOOLS_LOG_DIR"
    LOG_FILE="$LOG_DIR/deploy.log"
    mkdir -p "$LOG_DIR"
    ERRORS=0
}

# ---------------------------------------------------------------------------
# Standard logging (Pattern A: tee to stdout + log file)
# ---------------------------------------------------------------------------
log()       { printf '[%s] [%s] %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$SCRIPT_NAME" "$1" | tee -a "$LOG_FILE"; }
log_ok()    { log "OK: $1"; }
log_error() { log "ERROR: $1"; ERRORS=$((ERRORS + 1)); }
log_warn()  { log "WARN: $1"; }

# ---------------------------------------------------------------------------
# Summary writer (3-arg: category, tool, detail)
# ---------------------------------------------------------------------------
write_summary() {
    [ -n "${AITOOLS_SUMMARY_FILE:-}" ] && printf '%s|%s|%s\n' "$1" "$2" "$3" >> "$AITOOLS_SUMMARY_FILE"
}

# ---------------------------------------------------------------------------
# Summary panel renderer
# ---------------------------------------------------------------------------
# Reads AITOOLS_SUMMARY_FILE, displays colored panel, cleans up.
# Silent no-op if file unset, missing, or empty.
show_summary() {
    local sfile="${AITOOLS_SUMMARY_FILE:-}"
    [ -n "$sfile" ] || return 0
    [ -f "$sfile" ] || return 0
    [ -s "$sfile" ] || { rm -f "$sfile"; return 0; }
    echo ""
    echo "────────────────────────────────────────────────────────"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "OK"   ] && printf '\033[32m  [ok]  %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "WARN" ] && printf '\033[33m  [!]   %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "ERROR" ] && printf '\033[31m  [ERR] %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    local first_action=true
    while IFS='|' read -r cat tool detail; do
        if [ "$cat" = "ACTION" ]; then
            if [ "$first_action" = true ]; then
                echo ""
                printf '\033[1;35m  ACTION REQUIRED -- run before tools are ready:\033[0m\n'
                first_action=false
            fi
            printf '\033[1;35m  >>  %s\033[0m\n' "$detail"
        fi
    done < "$sfile"
    echo "────────────────────────────────────────────────────────"
    rm -f "$sfile"
}
logging_init "setup-typst"

# --- OS guard ---
case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*)
        log_error "This script is for macOS/Linux. On Windows, use ${SCRIPT_NAME}.ps1 instead."
        exit 1 ;;
esac

# --- Cleanup non-preferred installs ---
# Cargo typst-cli conflicts with Homebrew typst (different binary paths)
if command -v cargo &>/dev/null; then
    # Cleanup: cargo package may not be installed; non-blocking -- Homebrew install follows
    cargo uninstall typst-cli 2>/dev/null || true
fi
# npm typst is a third-party wrapper, not official
if command -v npm &>/dev/null; then
    # Cleanup: npm package may not be installed; non-blocking -- Homebrew install follows
    npm uninstall -g typst 2>/dev/null || true
fi

# --- Install/update ---
if command -v typst &>/dev/null; then
    typst_path=$(command -v typst)
    if [[ "$typst_path" == /opt/homebrew/* ]] || [[ "$typst_path" == /usr/local/* ]]; then
        log "Already installed via Homebrew -- upgrading..."
        UPGRADE_OUTPUT=$(brew upgrade typst 2>&1) || true
        if printf '%s\n' "$UPGRADE_OUTPUT" | grep -qi 'already installed\|up.to.date\|No available upgrade'; then
            log_ok "Typst already up to date"
        else
            printf '%s\n' "$UPGRADE_OUTPUT" | while IFS= read -r line; do log "$line"; done
            if printf '%s\n' "$UPGRADE_OUTPUT" | grep -qi 'error\|fatal'; then
                log_error "brew upgrade typst failed (see log above)"
                write_summary ERROR "typst" "brew upgrade failed"
            fi
        fi
        log_ok "$(typst --version)"
        write_summary OK "typst" "$(typst --version)"
    else
        log_warn "Typst installed via non-preferred method at $typst_path"
        log "Migrating to Homebrew..."
        if ! brew install typst 2>&1 | while IFS= read -r line; do log "$line"; done; then
            log_error "brew install typst failed"
            write_summary ERROR "typst" "brew install failed"
        fi
        if command -v typst &>/dev/null; then
            log_ok "Migrated to Homebrew: $(typst --version)"
            write_summary OK "typst" "$(typst --version)"
        else
            log_error "brew install succeeded but 'typst' not found in PATH"
            write_summary ERROR "typst" "installed but not on PATH"
        fi
    fi
else
    log "Installing Typst via Homebrew..."
    if ! brew install typst 2>&1 | while IFS= read -r line; do log "$line"; done; then
        log_error "brew install typst failed"
        write_summary ERROR "typst" "brew install failed"
    fi
    if command -v typst &>/dev/null; then
        log_ok "Typst installed ($(typst --version))"
        write_summary OK "typst" "$(typst --version)"
    else
        log_error "brew install completed but 'typst' not found in PATH"
        write_summary ERROR "typst" "installed but not on PATH"
    fi
fi

# --- Exit ---
if [ "$ERRORS" -gt 0 ]; then
    log "FAILED with $ERRORS error(s). See log: $LOG_FILE"
    exit 1
else
    log "COMPLETED successfully"
    exit 0
fi
